actual_metrics<-function() {
 grid::grid.force();x<-collect_grob_text(g);allow<-unlist(spec$text_contract$allowed_text)
 stopifnot(length(x$labels)>0,all(x$families=='Arial'),min(x$sizes)>=6.5,max(x$sizes)<=7,all(x$labels[nzchar(x$labels)]%in%allow))
 bf_assert_no_footer_grob(g);bf_assert_scientific_grob_text(g);bf_assert_scientific_text(x$labels)
 chars<-unique(unlist(strsplit(paste(x$labels,collapse=''),'',fixed=TRUE)));stopifnot(all(systemfonts::glyph_info(chars[!chars%in%c('\n','\r','\t')],path=font$path,index=font$index)$index>0))
 vpbox<-function(name) {
  a<-g$layout[g$layout$name==name,,drop=FALSE];stopifnot(nrow(a)==1)
  grid::seekViewport(paste0(name,'.',a$t,'-',a$l,'-',a$b,'-',a$r));lo<-grid::deviceLoc(grid::unit(0,'npc'),grid::unit(0,'npc'),valueOnly=TRUE);hi<-grid::deviceLoc(grid::unit(1,'npc'),grid::unit(1,'npc'),valueOnly=TRUE);grid::upViewport(0)
  c(x=lo$x*25.4,y=lo$y*25.4,w=(hi$x-lo$x)*25.4,h=(hi$y-lo$y)*25.4)
 }
 panel<-vpbox('panel');legend<-vpbox('guide-box-right')
 z<-p$coordinates$transform(b$data[[1]],b$layout$panel_params[[1]]);z<-z[z$type=='interaction'&!is.na(z$fill),]
 # Measure actual final-device polygon edge vectors, not canvas ratios.
 e1<-cbind((z$xmin-z$x)*panel['w'],(z$ymin-z$y)*panel['h']);e2<-cbind((z$xmax-z$xmin)*panel['w'],(z$ymax-z$ymin)*panel['h'])
 a<-sqrt(rowSums(e1^2));c<-sqrt(rowSums(e2^2));rel<-abs(a/c-1);ang<-rowSums(e1*e2)/(a*c)
 stopifnot(all(is.finite(a)),min(a)>0,max(rel)<.01,max(abs(ang))<.01)
 boxes<-data.frame(id=c('data','legend'),rbind(panel,legend),row.names=NULL);bf_check_boxes(boxes,183,116)
 list(text=unique(x$labels),families=unique(x$families),sizes=unique(x$sizes),boxes=boxes,diamond_geometry=list(measurement='actual final panel viewport mm multiplied by native transformed polygon edge vectors',polygon_count=nrow(z),edge1_range_mm=range(a),edge2_range_mm=range(c),maximum_edge_relative_error=max(rel),maximum_absolute_edge_cosine=max(abs(ang)),native_layers=lapply(seq_along(b$data),function(i)list(layer=i,geom=class(p$layers[[i]]$geom)[1],rows=nrow(b$data[[i]])))))
}
grid::grid.newpage();grid::grid.draw(g);pm<-actual_metrics();dev.off()
stopifnot(identical(before,lapply(sources,bound)))
a<-jsonlite::fromJSON(auth,simplifyVector=FALSE);marker<-paste0(auth,'.consumed');stopifnot(trimws(readLines(marker)[1])==a$authorization_id)
write_json(list(schema_version=1,status='PASS',backend='R',renderer='gghic',artifact=bound(png),sources=before,authorization_consumption=list(consumed=TRUE,authorization_id=a$authorization_id,marker=bound(marker),authorization_file=bound(auth),preparation_receipt=a$bound$receipt),font=c(bound(font$path),list(family=font$family)),checks=list(font=TRUE,text_allowlist=TRUE,scientific_text_only=TRUE,footer_free=TRUE,layout=TRUE,target_size=TRUE,native_rotated_diamond_geometry=TRUE),rendered_text=as.list(pm$text),text_policy_id='scientific-content-only-v1',footer_policy_id='no-canvas-footer-v1',target_min_text_pt=min(pm$sizes),min_text_pt=6.5,target_width_mm=183,target_size=list(width_mm=183,height_mm=116,size_class='double-column',size_basis='final_physical_output'),device=list(width_mm=183,height_mm=116,dpi=400),boxes=pm$boxes,native_geometry=pm$diamond_geometry,scope='Exact current native rotated diamond polygons; no rectangular matrix slice claim. Scientific/visual review remains separate.'),paste0(png,'.render.json'))
bf_pdf_open(pdf,183,116,font);grid::grid.newpage();grid::grid.draw(g);dm<-actual_metrics();dev.off();pa<-bf_pdf_finalize(pdf,font,183,116)
write_json(pa,paste0(pdf,'.pdf-audit.json'));write_json(list(artifact=bound(pdf),source_png=bound(png),sources=before,rendered_text=as.list(dm$text),actual_font_sizes_pt=dm$sizes,boxes=dm$boxes,native_geometry=dm$diamond_geometry),paste0(pdf,'.export.json'))
write_json(list(png=pm,pdf=dm,warnings=warn),file.path(W,'actual-layout.json'));write_json(list(status='RENDERED_PENDING_VISUAL_REVIEW',png=bound(png),pdf=bound(pdf),authorization=bound(auth)),file.path(W,'run.json'));cat('RENDERED_PENDING_VISUAL_REVIEW\n')
